// Read by the welcome screen for its banner (chapter 10)
public static bool JustSaved = false;
public static int LastSavedScore = 0;
public static int PreviousBest = -1;   // best score before the save
public static int PreviousPlace = 0;   // place before the save

// Which banner shows after a save: A, B, C or D (chapter 10)
public static char BannerCase()
{
    int place = ScoreFile.PlaceOf(CurrentPlayer.Username);
    if (place == 0) return 'D';
    if (PreviousPlace == 0) return 'A';
    if (LastSavedScore > PreviousBest) return 'B';
    return 'C';
}

// The banner's heading
public static string BannerHeading()
{
    switch (BannerCase())
    {
        case 'A': return "You made the Top 10!";
        case 'B': return "New best score!";
        case 'C': return "Still in the Top 10";
        default: return "Expedition saved";
    }
}

// The banner's message
public static string BannerMessage()
{
    string name = CurrentPlayer.Username;
    int place = ScoreFile.PlaceOf(name);
    string ordinal = Mix.Ordinal(place);
    string row = " Your row is highlighted on the board.";
    switch (BannerCase())
    {
        case 'A':
            return "Your score of " + LastSavedScore
                + " points puts you " + ordinal + "." + row;
        case 'B':
            string move = "moves you up to ";
            if (place == PreviousPlace) move = "keeps you ";
            return "Your new best of " + LastSavedScore + " points "
                + move + ordinal + "." + row;
        case 'C':
            return "You scored " + LastSavedScore + " points this "
                + "time. Your best of " + ScoreFile.BestScore(name)
                + " points keeps you " + ordinal + "." + row;
        default:
            return "You scored " + LastSavedScore + " points. The "
                + "Top 10 starts at " + ScoreFile.TenthPlaceScore()
                + " points. Beat that to get on the board.";
    }
}

// Fills in the title, the total and one line for each summit
private void frmFeedback_Load(object sender, EventArgs e)
{
    if (Expedition.DoneCount() < 8)
    {
        lblTitle.Text = "Expedition finished early";
    }
    this.Text = lblTitle.Text;
    lblTotal.Text = "You scored " + Expedition.Total()
        + " out of 800 points.";
    for (int i = 0; i < 8; i++)
    {
        if (Expedition.Done[i])
        {
            lstGames.Items.Add(Expedition.Games[i] + ": "
                + Expedition.Results[i].Score + " out of 100 points");
        }
        else
        {
            lstGames.Items.Add(Expedition.Games[i] + ": not climbed");
        }
    }
}

// Shows the chosen summit's score and every line about it
private void lstGames_SelectedIndexChanged(object sender,
    EventArgs e)
{
    int i = lstGames.SelectedIndex;
    if (i == -1) return;           // nothing is selected
    lblGameName.Text = Expedition.Games[i];
    txtWell.Clear();
    txtWrong.Clear();
    if (!Expedition.Done[i])
    {
        lblGameScore.Text = "You did not climb this summit, so it "
            + "scored 0.";
        prgGame.Visible = false;
        return;
    }
    GameResult result = Expedition.Results[i];
    lblGameScore.Text = "You scored " + result.Score
        + " out of 100 points.";
    prgGame.Value = result.Score;
    prgGame.Visible = true;
    foreach (string line in result.WentWell)
    {
        txtWell.AppendText("• " + line + Environment.NewLine);
    }
    foreach (string line in result.WentWrong)
    {
        txtWrong.AppendText("• " + line + Environment.NewLine);
    }
}

// Saves the score, and remembers what the banner needs to know
private void btnSave_Click(object sender, EventArgs e)
{
    string name = Expedition.CurrentPlayer.Username;
    Expedition.PreviousBest = ScoreFile.BestScore(name);
    Expedition.PreviousPlace = ScoreFile.PlaceOf(name);
    string date = DateTime.Now.ToString("dd/MM/yyyy HH:mm");
    ScoreFile.Save(new ScoreEntry(name, Expedition.Total(), date));
    Expedition.JustSaved = true;
    Expedition.LastSavedScore = Expedition.Total();
    Saved = true;
    this.Close();
}

// Runs as the window closes: asks first if nothing was saved
private void frmFeedback_FormClosing(object sender,
    FormClosingEventArgs e)
{
    if (Saved) return;
    DialogResult answer = MessageBox.Show("Leave without saving your "
        + "score? This expedition will not count.", "Summit Ready",
        MessageBoxButtons.YesNo);
    if (answer == DialogResult.No) e.Cancel = true;   // stay
}

// Shows how it went; once the score is saved, the map closes
private void OpenFeedback()
{
    this.Hide();
    frmFeedback feedback = new frmFeedback();
    feedback.ShowDialog();
    if (feedback.Saved)
    {
        saved = true;
        this.Close();
    }
    else
    {
        this.Show();
    }
}

// The banner shows once, straight after a saved expedition
private void ShowBanner()
{
    if (!Expedition.JustSaved)
    {
        MoveBoard(false);
        return;
    }
    Expedition.JustSaved = false;      // once only
    char bannerCase = Expedition.BannerCase();
    lblBannerHead.Text = Expedition.BannerHeading();
    lblBannerMessage.Text = Expedition.BannerMessage();
    picTrophy.Visible = bannerCase != 'D';
    if (bannerCase == 'A' || bannerCase == 'B') Sound.Play("win.wav");
    MoveBoard(true);
}
